#ifndef A04_OWNER_TRANSFER_H
#define A04_OWNER_TRANSFER_H
#include <stdint.h>
/* All callbacks must be serialized and bounded. acquire reserves exclusively
 * but MUST NOT access I2C until this routine returns NEW. On failure no side
 * may access I2C; recovery is external. Callback success is platform-supplied
 * evidence, not proof generated by this core. */
struct a04_transfer_ops {
    void *context;
    int (*close_admission)(void *);
    int (*drain)(void *);
    int (*release)(void *);
    int (*acquire)(void *);
    uint64_t (*now_ns)(void *);
};
enum a04_transfer_state { A04_TRANSFER_OLD, A04_TRANSFER_TRANSITION,
    A04_TRANSFER_NEW, A04_TRANSFER_FAILED };
struct a04_owner_transfer { enum a04_transfer_state state; int attempted; };
int a04_owner_transfer_run(struct a04_owner_transfer *,const struct a04_transfer_ops *,uint64_t deadline);
#endif
